const tiles=8,tw=Math.ceil(w/tiles),th=Math.ceil(h/tiles),maps=[];for(let ty=0;ty<tiles;ty++)for(let tx=0;tx<tiles;tx++){const hh=new Uint32Array(256);let area=0;for(let y=ty*th;y<Math.min((ty+1)*th,h);y++)for(let x=tx*tw;x<Math.min((tx+1)*tw,w);x++){hh[blur[y*w+x]]++;area++}const limit=Math.max(1,Math.round(2.3*area/256));let excess=0;for(let k=0;k<256;k++)if(hh[k]>limit){excess+=hh[k]-limit;hh[k]=limit}const each=Math.floor(excess/256),rem=excess%256;const lut=new Uint8ClampedArray(256);let cumulative=0;for(let k=0;k<256;k++){hh[k]+=each+(k<rem?1:0);cumulative+=hh[k];lut[k]=area?255*cumulative/area:k}maps.push(lut)}const enhanced=new Uint8ClampedArray(n);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const fx=x/tw-.5,fy=y/th-.5,x0=Math.floor(fx),y0=Math.floor(fy),ax=fx-x0,ay=fy-y0,ix0=Math.max(0,Math.min(tiles-1,x0)),ix1=Math.max(0,Math.min(tiles-1,x0+1)),iy0=Math.max(0,Math.min(tiles-1,y0)),iy1=Math.max(0,Math.min(tiles-1,y0+1)),v=blur[y*w+x];enhanced[y*w+x]=(1-ay)*((1-ax)*maps[iy0*tiles+ix0][v]+ax*maps[iy0*tiles+ix1][v])+ay*((1-ax)*maps[iy1*tiles+ix0][v]+ax*maps[iy1*tiles+ix1][v]);hist[enhanced[y*w+x]]++}
const magnitude=new Float32Array(n);let gradSq=0;for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){const i=y*w+x,a=enhanced,gx=-a[i-w-1]+a[i-w+1]-2*a[i-1]+2*a[i+1]-a[i+w-1]+a[i+w+1],gy=-a[i-w-1]-2*a[i-w]-a[i-w+1]+a[i+w-1]+2*a[i+w]+a[i+w+1],v=Math.hypot(gx,gy);magnitude[i]=v;gradSq+=v*v}const edgeThreshold=Math.max(55,Math.sqrt(gradSq/n)*1.25),edges=new Uint8ClampedArray(n);for(let i=0;i<n;i++)edges[i]=magnitude[i]>edgeThreshold?255:0;
let totalSum=0;for(let i=0;i<256;i++)totalSum+=i*hist[i];let bgW=0,bgS=0,best=-1,otsu=0;for(let t=0;t<256;t++){bgW+=hist[t];if(!bgW)continue;const fgW=n-bgW;if(!fgW)break;bgS+=t*hist[t];const v=bgW*fgW*(bgS/bgW-(totalSum-bgS)/fgW)**2;if(v>best){best=v;otsu=t}}const binary=new Uint8ClampedArray(n);for(let i=0;i<n;i++)binary[i]=enhanced[i]>otsu?255:0;function morph(src,dilate){const out=new Uint8ClampedArray(n);for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){let v=dilate?0:255;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)v=dilate?Math.max(v,src[(y+dy)*w+x+dx]):Math.min(v,src[(y+dy)*w+x+dx]);out[y*w+x]=v}return out}const closed=morph(morph(edges,true),false);
